package com.voicetxt.reader;
import android.app.*;import android.content.*;import android.os.*;import com.google.android.gms.tasks.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
public class MultilingualTranslationTest extends Instrumentation {
    Bundle arguments;void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
    void ui(Runnable action){AtomicReference<Throwable> error=new AtomicReference<>();runOnMainSync(()->{try{action.run();}catch(Throwable e){error.set(e);}});if(error.get()!=null)throw new AssertionError(error.get());}
    void await(java.util.function.BooleanSupplier predicate,String message)throws Exception{long end=SystemClock.elapsedRealtime()+60000;while(SystemClock.elapsedRealtime()<end){AtomicBoolean value=new AtomicBoolean();ui(()->value.set(predicate.getAsBoolean()));if(value.get())return;Thread.sleep(60);}throw new AssertionError(message);}
    String read(File file)throws Exception{try(InputStream in=new FileInputStream(file)){return new String(MainActivity.readBytes(in),StandardCharsets.UTF_8);}}
    void stage(String message){Bundle status=new Bundle();status.putString("stage",message);sendStatus(1,status);}
    public void onCreate(Bundle args){super.onCreate(args);arguments=args;start();}
    public void onStart(){Bundle result=new Bundle();Context context=getTargetContext();OfflineTranslation translation=null;MainActivity activity=null;SharedPreferences prefs=context.getSharedPreferences("reading_settings",0);Map<String,?> saved=new HashMap<>(prefs.getAll());final String preferredChinese=prefs.getString("systemVoiceKey","");boolean passed=false;try{
        if(arguments.getString("phase","").equals("status")){android.app.DownloadManager manager=context.getSystemService(android.app.DownloadManager.class);StringBuilder state=new StringBuilder();try(android.database.Cursor rows=manager.query(new android.app.DownloadManager.Query())){while(rows!=null&&rows.moveToNext()){state.append("status=").append(rows.getInt(rows.getColumnIndexOrThrow(android.app.DownloadManager.COLUMN_STATUS))).append(" reason=").append(rows.getInt(rows.getColumnIndexOrThrow(android.app.DownloadManager.COLUMN_REASON))).append(" bytes=").append(rows.getLong(rows.getColumnIndexOrThrow(android.app.DownloadManager.COLUMN_BYTES_DOWNLOADED_SO_FAR))).append('/').append(rows.getLong(rows.getColumnIndexOrThrow(android.app.DownloadManager.COLUMN_TOTAL_SIZE_BYTES))).append(';');}}result.putString("downloads",state.toString());try(android.database.Cursor raw=context.getContentResolver().query(android.net.Uri.parse("content://downloads/my_downloads"),new String[]{"_id","status","numfailed","uri","errorMsg"},null,null,null)){StringBuilder diagnostic=new StringBuilder();while(raw!=null&&raw.moveToNext()){String error=raw.getString(4);if(error==null)error="";error=error.replaceAll("https?://[^\\s]+","<url>");diagnostic.append("status=").append(raw.getInt(1)).append(" failures=").append(raw.getInt(2)).append(" host=").append(android.net.Uri.parse(raw.getString(3)).getHost()).append(" error=").append(error.substring(0,Math.min(180,error.length()))).append(';');}result.putString("modelNetwork",diagnostic.toString());}catch(Exception error){result.putString("diagnostic",error.getClass().getSimpleName());}finish(-1,result);return;}
        translation=new OfflineTranslation(context);Tasks.await(translation.available(),30,TimeUnit.SECONDS);String original=read(new File(context.getFilesDir(),"book_660fa497-5a19-4ee6-94eb-15a4035f34b4.txt"));List<String> lines=new ArrayList<>();List<Integer> offsets=new ArrayList<>();for(int at=0;at<original.length();){while(at<original.length()&&Character.isWhitespace(original.charAt(at)))at++;if(at>=original.length())break;int end=TranslationText.end(original,at,original.length());String input=original.substring(at,end);if(TranslationText.speakable(input)){lines.add(input);offsets.add(at);}at=end;}OfflineTranslation.Session session=translation.session(lines,"zh",original,offsets);Set<String> missing=session.missingUpcoming(Integer.MAX_VALUE);Set<String> languages=new LinkedHashSet<>();int headings=0;String expected="";List<Integer> examples=new ArrayList<>();Set<String> exampleLanguages=new HashSet<>();for(int i=0;i<lines.size();i++){TranslationText.Heading heading=TranslationText.heading(lines.get(i));if(heading!=null){expected=heading.code;headings++;continue;}for(OfflineTranslation.Unit unit:session.plan(i)){if(!TranslationText.speakable(unit.text))continue;languages.add(unit.source);check(unit.source.equals(expected),"source misidentified at "+i+": "+unit.source+" expected "+expected);if(exampleLanguages.add(unit.source))examples.add(i);}}
        check(headings==15&&languages.size()==14,"not all 15 sections inspected");check(translation.cache.getName().equals("translations-v3"),"stale cache namespace");int english=-1;for(int i:examples)if(session.plan(i).get(0).source.equals("en")){english=i;break;}check(english>=0,"English not found");String chinese=session.get(english);check(chinese.codePoints().anyMatch(c->Character.UnicodeScript.of(c)==Character.UnicodeScript.HAN),"English was not translated to Chinese");result.putString("englishToChinese",chinese);result.putInt("sections",headings);result.putString("detectedLanguages",languages.toString());result.putString("missingModels",missing.toString());stage("All 15 user-document sections identified; English translated to Chinese; missing "+missing);
        int availableExamples=0;StringBuilder availableOutputs=new StringBuilder();OfflineTranslation.Session availableEnglish=translation.session(lines,"en",original,offsets);for(int index:examples){if(!session.required(session.plan(index)).isEmpty())continue;String output=session.get(index);check(output.codePoints().anyMatch(c->Character.UnicodeScript.of(c)==Character.UnicodeScript.HAN),"available model did not translate to Chinese");String englishOutput=availableEnglish.get(index);check(englishOutput.codePoints().anyMatch(c->c>='A'&&c<='z'),"available model did not translate to English");availableOutputs.append(session.plan(index).get(0).source).append(": ").append(output).append('\n');availableExamples++;}result.putInt("availableSourceLanguagesValidated",availableExamples);result.putString("availableTranslations",availableOutputs.toString());
        if(arguments.getString("phase","").equals("audit")){int rejected=0,burmese=0;for(Map.Entry<String,String> entry:session.detected.entrySet()){int separator=entry.getKey().indexOf(':');int group=Integer.parseInt(entry.getKey().substring(0,separator));List<com.google.mlkit.nl.languageid.IdentifiedLanguage> guesses=Tasks.await(translation.identifier.identifyPossibleLanguages(entry.getKey().substring(separator+1)),20,TimeUnit.SECONDS);String top="und";float score=0;for(com.google.mlkit.nl.languageid.IdentifiedLanguage guess:guesses)if(guess.getConfidence()>score){top=OfflineTranslation.normalize(guess.getLanguageTag());score=guess.getConfidence();}if(!top.equals("und")&&!LanguageRules.compatible(group,top)){rejected++;if(top.equals("my"))burmese++;}}result.putInt("incompatibleTopGuessesRejected",rejected);result.putInt("falseBurmeseGuessesRejected",burmese);result.putString("result","PASS: full real user test document, 15 sections/14 codes; all installed source models; Chinese and English translations; no false missing models; script-compatible detection");passed=true;finish(-1,result);return;}
        if(arguments.getString("phase","inspect").equals("download")){
            if(!missing.isEmpty()){activity=(MainActivity)startActivitySync(new Intent(context,MainActivity.class).putExtra("book_id","multilingual_translation_qa").putExtra("book_name","离线语言包准备").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final MainActivity downloading=activity;ui(()->{downloading.getWindow().addFlags(android.view.WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);downloading.setReaderStatus("正在准备离线语言包");});String retry=arguments.getString("retryModel","");if(missing.contains(retry)&&!translation.installed.contains(retry)){stage("Resetting only the incomplete model request: "+retry);Tasks.await(com.google.mlkit.common.model.RemoteModelManager.getInstance().deleteDownloadedModel(new com.google.mlkit.nl.translate.TranslateRemoteModel.Builder(retry).build()),20,TimeUnit.SECONDS);}final OfflineTranslation owner=translation;Task<Void> download=translation.prepare(missing,()->true,(done,total,language)->{stage("Models "+done+" / "+total+": "+language);downloading.runOnUiThread(()->{if(!downloading.destroyed)downloading.setReaderStatus("离线语言包 "+done+" / "+total+": "+language);});});long end=SystemClock.elapsedRealtime()+1500000;while(!download.isComplete()&&SystemClock.elapsedRealtime()<end)Thread.sleep(250);check(download.isComplete(),"model download test deadline");Tasks.await(download,1,TimeUnit.SECONDS);Tasks.await(owner.available(),20,TimeUnit.SECONDS);ui(()->downloading.finish());activity=null;}
            StringBuilder outputs=new StringBuilder();for(int index:examples){String output=session.get(index);check(output.codePoints().anyMatch(c->Character.UnicodeScript.of(c)==Character.UnicodeScript.HAN),"not Chinese: "+session.plan(index).get(0).source);outputs.append(session.plan(index).get(0).source).append(": ").append(output).append('\n');}result.putString("translatedSamples",outputs.toString());OfflineTranslation.Session toEnglish=translation.session(lines,"en",original,offsets);for(int index:examples){String output=toEnglish.get(index);check(output.codePoints().anyMatch(c->c>='A'&&c<='z'),"not English for "+session.plan(index).get(0).source);}result.putBoolean("allSourceLanguagesToChineseAndEnglish",true);
        }
        activity=(MainActivity)startActivitySync(new Intent(context,MainActivity.class).putExtra("book_id","multilingual_translation_qa").putExtra("book_name","多语言译读验证").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final MainActivity a=activity;await(()->a.offlineReady&&a.system.initialized,"voices not ready");final Set<String> needed=missing;ui(()->{a.stop();a.text=original;a.chapters=MainActivity.parse(original);a.position=0;a.loopPlayback=false;a.readingLanguage="zh";a.systemVoiceKey=a.system.offlineVoice("zh",preferredChinese).key;a.showPosition(true);a.startReading();});if(!needed.isEmpty()&&!arguments.getString("phase","inspect").equals("download")){await(()->!a.playing&&a.translationModelsDialog!=null&&a.translationModelsDialog.isShowing(),"missing model dialog not shown");ui(()->{check(a.position==0,"missing-model preflight skipped text");check(PlaybackService.active!=null&&!PlaybackService.active.foreground,"missing models kept foreground/wake");a.translationModelsDialog.getButton(AlertDialog.BUTTON_NEGATIVE).performClick();a.stop();});result.putBoolean("missingModelPromptKeepsPosition",true);}
        ui(()->{a.stop();a.text="English\nThe little horse is reading a book. The sunshine makes the garden warm.";a.chapters=MainActivity.parse(a.text);a.position=0;a.readingLanguage="zh";a.systemVoiceKey=a.system.offlineVoice("zh",preferredChinese).key;a.loopPlayback=false;a.startReading();});await(()->a.latestStatus.startsWith(a.getString(R.string.ui_83))&&a.position>=8,"translated system Chinese body speech did not start");ui(()->{check(a.system.find(a.systemVoiceKey).voice.getLocale().getLanguage().equals("zh"),"wrong target speech voice");a.stop();a.startReading();a.stop();});Thread.sleep(700);ui(()->check(!a.playing&&a.translatedSession==null,"cancelled preparation resumed"));
        if(a.translation.installed.contains("ja")&&a.translation.installed.contains("fr")){ui(()->{a.text="**日本語**\n今日は良い天気です。公園で本を読みます。\n**Français**\nLe soleil brille dans le jardin. Le petit cheval lit un livre.";a.chapters=MainActivity.parse(a.text);a.position=0;a.readingLanguage="zh";a.systemVoiceKey="";a.offlineVoice=2015;a.startReading();});await(()->a.latestStatus.startsWith(a.getString(R.string.ui_83))&&a.position>=8,"multilingual native Chinese body speech did not start");ui(()->a.stop());result.putBoolean("multilingualNativeChinesePlayback",true);}
        result.putString("result","PASS: exact user document 15 sections / 14 language codes; mixed-script and heading detection; English translated before Chinese voice; v3 cache; missing-model preflight preserves position; cancel prevents stale playback"+(arguments.getString("phase","inspect").equals("download")?"; all source languages translated to Chinese and English; multilingual native Chinese playback":""));passed=true;
    }catch(Throwable error){result.putString("error",android.util.Log.getStackTraceString(error));if(activity!=null){final MainActivity debug=activity;ui(()->result.putString("playbackState","status="+debug.latestStatus+" playing="+debug.playing+" position="+debug.position+" generation="+debug.generation+" focus="+debug.focusGeneration+" service="+(PlaybackService.active!=null)+" host="+(PlaybackService.host!=null)+" destroyed="+debug.destroyed+" translation="+(debug.translatedSession!=null)));}}finally{if(activity!=null){final MainActivity a=activity;ui(()->{a.stop();a.finish();});}if(translation!=null)translation.close();SharedPreferences.Editor restore=prefs.edit().clear();for(Map.Entry<String,?> entry:saved.entrySet()){Object value=entry.getValue();if(value instanceof String)restore.putString(entry.getKey(),(String)value);else if(value instanceof Integer)restore.putInt(entry.getKey(),(Integer)value);else if(value instanceof Boolean)restore.putBoolean(entry.getKey(),(Boolean)value);else if(value instanceof Float)restore.putFloat(entry.getKey(),(Float)value);else if(value instanceof Long)restore.putLong(entry.getKey(),(Long)value);}restore.commit();context.getSharedPreferences("reader_multilingual_translation_qa",0).edit().clear().commit();new File(context.getFilesDir(),"book_multilingual_translation_qa.txt.position").delete();}finish(passed?-1:0,result);}
}



